/* RFC 8949 Section 3.3: 0xF8 followed by a byte below 0x20 is not
 * well-formed. Values 0..23 must use the one-byte encoding and 24..31 are
 * reserved. */
unsigned char simple_value_two_byte_0_data[] = {0xF8, 0x00};
unsigned char simple_value_two_byte_23_data[] = {0xF8, 0x17};
unsigned char simple_value_24_data[] = {0xF8, 0x18};
unsigned char simple_value_31_data[] = {0xF8, 0x1F};
static void test_simple_value_reserved_decoding(void** _state _CBOR_UNUSED) {
  assert_decoder_result(0, CBOR_DECODER_ERROR,
                        decode(simple_value_two_byte_0_data, 2));
  assert_decoder_result(0, CBOR_DECODER_ERROR,
                        decode(simple_value_two_byte_23_data, 2));
  assert_decoder_result(0, CBOR_DECODER_ERROR, decode(simple_value_24_data, 2));
  assert_decoder_result(0, CBOR_DECODER_ERROR, decode(simple_value_31_data, 2));
}

static void test_simple_values(void** _state _CBOR_UNUSED) {
  // 0..23 use the one-byte encoding
  assert_size_equal(1, cbor_encode_ctrl(0, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xE0}), 1);
  assert_size_equal(1, cbor_encode_ctrl(19, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xF3}), 1);
  assert_size_equal(1, cbor_encode_ctrl(20, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xF4}), 1);
  assert_size_equal(1, cbor_encode_ctrl(23, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xF7}), 1);

  // 32..255 use the two-byte encoding
  assert_size_equal(2, cbor_encode_ctrl(32, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0x20}), 2);
  assert_size_equal(2, cbor_encode_ctrl(255, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0xFF}), 2);

  // 24..31 are reserved by RFC 8949 and have no well-formed encoding. The
  // encoder does not reject them; this pins the current (ill-formed) output
  // so that any change is deliberate.
  assert_size_equal(2, cbor_encode_ctrl(24, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0x18}), 2);
  assert_size_equal(2, cbor_encode_ctrl(31, buffer, 512));
  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0x1F}), 2);

  // Insufficient buffer
  assert_size_equal(0, cbor_encode_ctrl(0, buffer, 0));
  assert_size_equal(0, cbor_encode_ctrl(32, buffer, 1));
}

unsigned char simple_value_data[][2] = {
    {0xE0, 0x00}, {0xF3, 0x00}, {0xF8, 0x20}, {0xF8, 0xFF}};
size_t simple_value_lengths[] = {1, 1, 2, 2};
uint8_t simple_values[] = {0, 19, 32, 255};

/* Unassigned simple values are well-formed and must round-trip */
static void test_simple_values(void** _state _CBOR_UNUSED) {
  for (size_t i = 0; i < 4; i++) {
    float_ctrl = cbor_load(simple_value_data[i], simple_value_lengths[i], &res);
    assert_non_null(float_ctrl);
    assert_size_equal(res.read, simple_value_lengths[i]);
    assert_true(cbor_isa_float_ctrl(float_ctrl));
    assert_true(cbor_float_ctrl_is_ctrl(float_ctrl));
    assert_true(cbor_float_get_width(float_ctrl) == CBOR_FLOAT_0);
    assert_false(cbor_is_bool(float_ctrl));
    assert_false(cbor_is_null(float_ctrl));
    assert_false(cbor_is_undef(float_ctrl));
    assert_int_equal(cbor_ctrl_value(float_ctrl), simple_values[i]);

    unsigned char buffer[2];
    assert_size_equal(cbor_serialize(float_ctrl, buffer, 2),
                      simple_value_lengths[i]);
    assert_memory_equal(buffer, simple_value_data[i], simple_value_lengths[i]);

    cbor_decref(&float_ctrl);
    assert_null(float_ctrl);
  }
}

