static inline void cbor_decref(cbor_item_t** item_ref) {
  cbor_item_t* item = *item_ref;
  CBOR_ASSERT(item->refcount > 0);
  if (--item->refcount == 0) {
    _cbor_decref_free(item);
    *item_ref = NULL;
  }
}

static inline void cbor_decref(cbor_item_t** item_ref) {
  cbor_item_t* item = *item_ref;
  CBOR_ASSERT(item->refcount > 0);
  if (--item->refcount == 0) {
    _cbor_decref_free(item);
    *item_ref = NULL;
  }
}

void *limited_malloc(size_t size) {
    if (size + allocated_mem > kMemoryLimit) {
        return nullptr;
    }
    if (size == 0) {
        return nullptr;
    }
    void* m = malloc(size);
    if (m != nullptr) {
        allocated_mem += size;
        allocated_len_map[m] = size;
    }
    return m;
}

void *limited_malloc(size_t size) {
