void cbor_builder_float8_callback(void* context, double value) {
  struct _cbor_decoder_context* ctx = context;
  cbor_item_t* res = cbor_new_float8();
  CHECK_RES(ctx, res);
  cbor_set_float8(res, value);
  _cbor_builder_append(res, ctx);
}

